/** The guard predicates of the specimen machine, implemented once by the domain (SpecimenGuards). */
@Suppress("TooManyFunctions")
interface SpecimenPredicates {
    /**
     * at least one order this specimen serves is in the order machine's state active (signed, verified where verification applies, not on
     * hold); pending-verification, on-hold, completed, revoked and entered-in-error do not count. The order states are the orders module's
     * answer: as recorded when the command is received online, or as last synced to the device offline (DN-054 item 9)
     */
    fun servedOrderActive(facts: SpecimenFacts): Boolean

    /**
     * the specimen serves at least one order, and every order it serves is either revoked or entered-in-error in the order machine, or
     * completed with no result derived from this specimen (the results module's answer). An empty order list counts as not ended, so the
     * specimen stays visible as open work (fails closed; DN-054 item 8)
     */
    fun servedOrdersEnded(facts: SpecimenFacts): Boolean

    /**
     * a wristband scan was read for this command (never typed); its source is a patient wristband, never a bed, room, location or chart
     * label (SI-01 clause b; CTRL-0001-4); the barcode (a DataMatrix with MRN and encounter, §12) decoded an MRN that equals the specimen
     * patient's MRN; the identity service confirms that the MRN's check digit is valid (CTRL-0001-7) and that the MRN is current, neither
     * merged into another record nor retired (SI-08); and the patient's name and date of birth, or the approximate-DOB flag, from the
     * record were shown on the device and the user confirmed them (SI-01 clauses a and d). A merged or retired MRN never matches through
     * the merge link: the command is refused, and the identity service raises the re-banding task. The same reading as
     * medication-administration's wristbandScanMatches (DN-053, DN-054 item 4)
     */
    fun wristbandScanMatches(facts: SpecimenFacts): Boolean

    /**
     * the user recorded that the patient wears no wristband or that it cannot be read, and no wristband scan in this bedside session
     * decoded an MRN. A band that scans, to this or to any other patient, never opens the override: a mismatch stays a hard stop (DN-054
     * item 3)
     */
    fun noUsableWristband(facts: SpecimenFacts): Boolean

    /**
     * an active two-identifier check was recorded in this bedside session: either the patient stated their name and date of birth and the
     * user confirmed both against the record shown on the device, or an identity document was read through the shell HAL (§9.1) and the
     * identity service matched it to the specimen's patient; the identity service confirms the MRN's check digit and that the MRN is
     * current; a room, bed or location never counts. A patient who cannot state their identity (a neonate, an unconscious or confused
     * patient) cannot pass this check and is re-banded (DN-054 item 3)
     */
    fun twoIdentifiersActivelyConfirmed(facts: SpecimenFacts): Boolean

    /** the user chose the override reason, no-wristband or wristband-unreadable, never defaulted (the channel adapter's 'chosen' mark) */
    fun identityOverrideReasonChosen(facts: SpecimenFacts): Boolean

    /**
     * the test catalogue marks no test the specimen serves as a pre-transfusion sample (SI-11; catalogue content is governed configuration
     * [HUMAN]); an unknown flag, or a specimen that serves no test, counts as a transfusion sample
     */
    fun notTransfusionSample(facts: SpecimenFacts): Boolean

    /**
     * the label content carries the specimen's accession barcode and the patient's two identifiers: the name in the patient's script and in
     * a Latin transliteration, and the MRN with a valid check digit plus the date of birth at its recorded precision or the approximate-DOB
     * flag; no identifier slot holds a room or bed (SI-01 clauses a to d; CTRL-0001-5). Downtime and alias-kit labels are held to the same
     * rule (CTRL-0001-8)
     */
    fun labelIdentifiersComplete(facts: SpecimenFacts): Boolean

    /**
     * the specimen has an accession number, and: when the command was issued online (connected to the on-site cell), the cell's accession
     * service issued it; when it was issued offline (the device lost the on-site cell, or runs in edge-agent or mobile offline mode; losing
     * the internet alone is not offline, SI-15 clause h), the number lies inside a pre-allocated, site-prefixed downtime accession block
     * assigned to this device and was not used before (SI-15 clause c; CTRL-0015-6; §9.7). The mode is the one in which the command was
     * issued, from the command's offline envelope. A number from neither source never counts (DN-054 item 10)
     */
    fun accessionFromPermittedSource(facts: SpecimenFacts): Boolean

    /**
     * the labels scanned belong to an alias or downtime kit (band and labels issued together, §9.1 alias pools, SAC-06): their accession
     * numbers lie inside the pre-allocated, site-prefixed block issued with that kit and were not used before, and the kit's identity (the
     * alias identity printed on its band and labels) is the specimen patient's, by the identity service's answer (SI-15 clause c; DN-054
     * item 5)
     */
    fun kitAccessionFromAllocatedBlock(facts: SpecimenFacts): Boolean

    /**
     * the user chose a reprint reason, never defaulted (the channel adapter's 'chosen' mark); the reprint is recorded with user, device and
     * time, and the reprinted labels carry the specimen's existing accession number
     */
    fun reprintReasonChosen(facts: SpecimenFacts): Boolean

    /**
     * the collector is the authenticated user of the command's session (the Trust Plane's answer), never a typed name, and the collecting
     * device is recorded. For a specimen the patient collected (the catalogue marks the specimen type), the collector recorded is the user
     * who receives and labels it in the patient's presence
     */
    fun collectorIdentified(facts: SpecimenFacts): Boolean

    /**
     * a clinical collection time, confirmed by the collector, is recorded apart from the system time of the command (SI-10 clause a). It is
     * not later than the recording time and not earlier than the start of this bedside session (the wristband scan or the active
     * two-identifier check), except for a specimen type the catalogue marks as patient-collected, whose time is the one the patient stated,
     * not later than the session start, and recorded as stated by the patient. An earlier time is back-dating and goes through
     * BackEnterDowntimeCollection or the privileged, audited back-dating path of the command handler (SI-10 clause b; CTRL-0010-4; DN-054
     * item 15)
     */
    fun collectionTimeRecorded(facts: SpecimenFacts): Boolean

    /**
     * the label on the tube was scanned after the patient was identified in this bedside session (the wristband scan, or on the override
     * path the active two-identifier check), on the same device, and its accession number equals this specimen's: the system's evidence
     * that the label was applied in the patient's presence (SAC-09). A session ends when another wristband is scanned, another patient is
     * identified, or the session is closed, so a label scanned after another patient's identification never matches. This does not detect a
     * wrong blood in tube (WBIT), a later LIS feature (DN-054 item 6)
     */
    fun labelledAtBedside(facts: SpecimenFacts): Boolean

    /**
     * the user holds the downtime back-entry privilege for laboratory collections (governed configuration, §9.26; a Trust Plane answer); a
     * recorded downtime episode (the platform-site record of the cell or device outage) covers the clinical collection time; and the audit
     * record can be written with the command (an audit outage refuses the command; it never runs unaudited)
     */
    fun downtimeBackEntryAllowed(facts: SpecimenFacts): Boolean

    /**
     * the collector's identity and the clinical collection time are entered from the paper downtime record; the time lies inside the
     * downtime episode and is not later than the recording time; the entry keeps that time as the clinical time and is labelled as
     * back-entry (SI-10 clauses b and c; CTRL-0010-5)
     */
    fun paperCollectionRecorded(facts: SpecimenFacts): Boolean

    /**
     * the tube's label was scanned at back-entry (never typed); its accession number equals the specimen's existing accession number, or,
     * for a specimen without one, lies inside a pre-allocated, site-prefixed downtime block and was not used before (SI-15 clause c); and
     * the two identifiers printed on the label were shown to the user and confirmed against the specimen patient's record (SI-01)
     */
    fun downtimeLabelConfirmed(facts: SpecimenFacts): Boolean

    /**
     * the specimen's label was scanned at dispatch (a transport scan event with user, device, location and time; §9.8 'transport tracking
     * by scan events'), and the scanned accession number equals this specimen's
     */
    fun dispatchScanRecorded(facts: SpecimenFacts): Boolean

    /**
     * the label was scanned (never typed) at laboratory receipt, the scanned accession number equals this specimen's, and the specimen
     * serves at least one order (§9.8 acceptance 1)
     */
    fun receiptScanMatchesOrder(facts: SpecimenFacts): Boolean

    /**
     * an acceptability check was recorded at or after receipt, the specimen has at least one eligible test (a test whose order is not
     * revoked or entered-in-error), and every eligible test passes every criterion for that test: the container is one the catalogue allows
     * for it; the volume is at least its catalogue minimum; the time from the clinical collection time to now is within its stability limit
     * (stability runs from the clinical time, SI-10); the recorded haemolysis, icterus, lipaemia and clotting are within its governed
     * limits; and the label matched at receipt. Catalogue values are governed configuration [HUMAN]; an unknown value fails that test
     * (DN-054 item 11)
     */
    fun acceptableForEveryTest(facts: SpecimenFacts): Boolean

    /** the exact complement of acceptableForEveryTest */
    fun notAcceptableForEveryTest(facts: SpecimenFacts): Boolean

    /**
     * an acceptability check was recorded at or after receipt and at least one eligible test passes every criterion for that test, as in
     * acceptableForEveryTest
     */
    fun acceptableForSomeTest(facts: SpecimenFacts): Boolean

    /**
     * the user holds the laboratory's accept-with-caveat privilege (governed configuration, §9.26; a Trust Plane answer), and the audit
     * record can be written with the command (an audit outage refuses the command; it never runs unaudited)
     */
    fun caveatAuthorised(facts: SpecimenFacts): Boolean

    /**
     * an acceptability check was recorded at or after receipt and the specimen has at least one eligible test, as in
     * acceptableForEveryTest; and the catalogue marks the specimen type as irreplaceable, or marks every failed criterion of every eligible
     * test as waivable for that test (governed configuration [HUMAN]); no failed criterion is a label or identity criterion, which is never
     * waived (DN-054 item 11)
     */
    fun caveatAllowedForSpecimen(facts: SpecimenFacts): Boolean

    /** the user chose the caveat reason, never defaulted (the channel adapter's 'chosen' mark) */
    fun caveatReasonChosen(facts: SpecimenFacts): Boolean

    /**
     * testing on this specimen has ended: every test it serves has a result in the result machine's final, amended or corrected state, or a
     * result cancelled or entered in error, or was rejected for this specimen at the acceptability check, or belongs to an order that was
     * revoked or entered in error. The result and order states are the results and orders modules' answers; a preliminary result does not
     * count. A specimen that serves no test has not finished (fails closed; DN-054 item 12)
     */
    fun allTestsFinished(facts: SpecimenFacts): Boolean

    /**
     * no test the specimen serves whose order is still open (not completed, revoked or entered-in-error) has a result that was cancelled or
     * entered in error with no final, amended or corrected result from this specimen
     */
    fun noTestNeedsRecollection(facts: SpecimenFacts): Boolean

    /** the exact complement of noTestNeedsRecollection */
    fun testNeedsRecollection(facts: SpecimenFacts): Boolean

    /**
     * a storage location (rack and position) was scanned for the specimen (never typed), with user and time (§9.8 'storage location for
     * add-ons')
     */
    fun storageLocationScanned(facts: SpecimenFacts): Boolean

    /**
     * the test catalogue sets no retention period for any test the specimen serves (governed configuration [HUMAN]); an unknown retention
     * rule, or a specimen that serves no test, counts as required, so the specimen is stored (fails closed)
     */
    fun retentionNotRequired(facts: SpecimenFacts): Boolean

    /**
     * the specimen has a recorded storage time, and now is at or after that time plus the longest catalogue retention period of the tests
     * it serves; an unknown period, or a specimen that serves no test, never elapses
     */
    fun retentionElapsed(facts: SpecimenFacts): Boolean

    /**
     * no legal hold is recorded on the specimen: no hold from the retention and legal-hold engine (§9.27; §13 DP-9 'never auto-delete') and
     * no forensic or medico-legal (MLC) hold, which the SI-21 forensic/MLC label places on the case; an unknown hold status counts as held
     * (DN-054 item 13)
     */
    fun noLegalHold(facts: SpecimenFacts): Boolean

    /**
     * the user chose a rejection reason (never defaulted; the channel adapter's 'chosen' mark) from the coded list: unlabelled,
     * mislabelled, haemolysed, clotted, insufficient, wrong-container, expired-stability (§8.4 lists unlabelled, haemolysed, insufficient,
     * wrong container and expired stability; §9.8 adds clotting and mislabelled; DN-054 item 2)
     */
    fun rejectionReasonChosen(facts: SpecimenFacts): Boolean

    /**
     * the user chose a rejection reason (never defaulted; the channel adapter's 'chosen' mark) and it is unlabelled or mislabelled: the
     * tube reached the laboratory without a label that scans to this specimen's accession number, so the receipt scan cannot succeed
     */
    fun labelDefectReasonChosen(facts: SpecimenFacts): Boolean

    /**
     * a user declared the specimen lost, with their identity and the time, after being shown the specimen's last scan event; a declaration
     * is a deliberate action, never raised automatically
     */
    fun lossDeclared(facts: SpecimenFacts): Boolean

    /**
     * the user holds the specimen entered-in-error privilege for this laboratory (governed configuration, §9.26; a Trust Plane answer), and
     * the audit record of the correction can be written with the command (an audit outage refuses the command; it never runs unaudited).
     * B.3's name, required on every exit from a terminal state (WP-0.5 spec §1.2)
     */
    fun privilegedAndAudited(facts: SpecimenFacts): Boolean

    /**
     * the user chose an entered-in-error reason from the governed list (content [HUMAN]), never defaulted (the channel adapter's 'chosen'
     * mark)
     */
    fun errorReasonEntered(facts: SpecimenFacts): Boolean
}

