    /** Evaluates [predicate] with the domain's single implementation [predicates]. */
    @Suppress("CyclomaticComplexMethod")
    fun holds(
        predicate: SpecimenPredicate,
        predicates: SpecimenPredicates,
        facts: SpecimenFacts,
    ): Boolean =
        when (predicate) {
            SpecimenPredicate.SERVED_ORDER_ACTIVE -> predicates.servedOrderActive(facts)
            SpecimenPredicate.SERVED_ORDERS_ENDED -> predicates.servedOrdersEnded(facts)
            SpecimenPredicate.WRISTBAND_SCAN_MATCHES -> predicates.wristbandScanMatches(facts)
            SpecimenPredicate.NO_USABLE_WRISTBAND -> predicates.noUsableWristband(facts)
            SpecimenPredicate.TWO_IDENTIFIERS_ACTIVELY_CONFIRMED -> predicates.twoIdentifiersActivelyConfirmed(facts)
            SpecimenPredicate.IDENTITY_OVERRIDE_REASON_CHOSEN -> predicates.identityOverrideReasonChosen(facts)
            SpecimenPredicate.NOT_TRANSFUSION_SAMPLE -> predicates.notTransfusionSample(facts)
            SpecimenPredicate.LABEL_IDENTIFIERS_COMPLETE -> predicates.labelIdentifiersComplete(facts)
            SpecimenPredicate.ACCESSION_FROM_PERMITTED_SOURCE -> predicates.accessionFromPermittedSource(facts)
            SpecimenPredicate.KIT_ACCESSION_FROM_ALLOCATED_BLOCK -> predicates.kitAccessionFromAllocatedBlock(facts)
            SpecimenPredicate.REPRINT_REASON_CHOSEN -> predicates.reprintReasonChosen(facts)
            SpecimenPredicate.COLLECTOR_IDENTIFIED -> predicates.collectorIdentified(facts)
            SpecimenPredicate.COLLECTION_TIME_RECORDED -> predicates.collectionTimeRecorded(facts)
            SpecimenPredicate.LABELLED_AT_BEDSIDE -> predicates.labelledAtBedside(facts)
            SpecimenPredicate.DOWNTIME_BACK_ENTRY_ALLOWED -> predicates.downtimeBackEntryAllowed(facts)
            SpecimenPredicate.PAPER_COLLECTION_RECORDED -> predicates.paperCollectionRecorded(facts)
            SpecimenPredicate.DOWNTIME_LABEL_CONFIRMED -> predicates.downtimeLabelConfirmed(facts)
            SpecimenPredicate.DISPATCH_SCAN_RECORDED -> predicates.dispatchScanRecorded(facts)
            SpecimenPredicate.RECEIPT_SCAN_MATCHES_ORDER -> predicates.receiptScanMatchesOrder(facts)
            SpecimenPredicate.ACCEPTABLE_FOR_EVERY_TEST -> predicates.acceptableForEveryTest(facts)
            SpecimenPredicate.NOT_ACCEPTABLE_FOR_EVERY_TEST -> predicates.notAcceptableForEveryTest(facts)
            SpecimenPredicate.ACCEPTABLE_FOR_SOME_TEST -> predicates.acceptableForSomeTest(facts)
            SpecimenPredicate.CAVEAT_AUTHORISED -> predicates.caveatAuthorised(facts)
            SpecimenPredicate.CAVEAT_ALLOWED_FOR_SPECIMEN -> predicates.caveatAllowedForSpecimen(facts)
            SpecimenPredicate.CAVEAT_REASON_CHOSEN -> predicates.caveatReasonChosen(facts)
            SpecimenPredicate.ALL_TESTS_FINISHED -> predicates.allTestsFinished(facts)
            SpecimenPredicate.NO_TEST_NEEDS_RECOLLECTION -> predicates.noTestNeedsRecollection(facts)
            SpecimenPredicate.TEST_NEEDS_RECOLLECTION -> predicates.testNeedsRecollection(facts)
            SpecimenPredicate.STORAGE_LOCATION_SCANNED -> predicates.storageLocationScanned(facts)
            SpecimenPredicate.RETENTION_NOT_REQUIRED -> predicates.retentionNotRequired(facts)
            SpecimenPredicate.RETENTION_ELAPSED -> predicates.retentionElapsed(facts)
            SpecimenPredicate.NO_LEGAL_HOLD -> predicates.noLegalHold(facts)
            SpecimenPredicate.REJECTION_REASON_CHOSEN -> predicates.rejectionReasonChosen(facts)
            SpecimenPredicate.LABEL_DEFECT_REASON_CHOSEN -> predicates.labelDefectReasonChosen(facts)
            SpecimenPredicate.LOSS_DECLARED -> predicates.lossDeclared(facts)
            SpecimenPredicate.PRIVILEGED_AND_AUDITED -> predicates.privilegedAndAudited(facts)
            SpecimenPredicate.ERROR_REASON_ENTERED -> predicates.errorReasonEntered(facts)
        }

    /** Applies [command] in [state] with [facts]; never changes state unless exactly one guard holds. */
    fun fire(
        state: SpecimenState,
        command: SpecimenCommand,
        predicates: SpecimenPredicates,
        facts: SpecimenFacts,
    ): Outcome<SpecimenState, SpecimenCommand, SpecimenPredicate, SpecimenEffect> =
        spec.fire(state, command) { holds(it, predicates, facts) }
}
